repo.bookings.py:
"""Booking records."""


class Booking:
    def __init__(self, hotel, nights):
        self.hotel = hotel
        self.nights = nights

    def __repr__(self):
        return "Booking(%r, %r)" % (self.hotel, self.nights)


ROWS = [('grand', 13), ('harbour', 22), ('grand', 49), ('plaza', 16), ('plaza', 14)]


def load_bookings():
    """Yield the stored bookings one at a time."""
    for hotel, nights in ROWS:
        yield Booking(hotel, nights)

repo.ordering.py:
"""Codes of bookings in order."""


def ranked_codes(bookings):
    """Return the nights of each booking as a text code, from the lowest number to the highest."""
    return sorted(str(x.nights) for x in bookings)


def code_of(booking):
    """Return the text code of one booking."""
    return str(booking.nights)


def hotel_names(bookings):
    """Return the distinct hotel values, in first-seen order."""
    names = []
    for x in bookings:
        if x.hotel not in names:
            names.append(x.hotel)
    return names


def describe_booking(booking):
    """Return a one-line description of a booking."""
    return "%s: %s" % (booking.hotel, booking.nights)

repo.tests/test_visible.py:
from bookings import Booking
from ordering import ranked_codes


def test_nine_before_ten():
    assert ranked_codes([Booking("a", 10), Booking("b", 9)]) == ["9", "10"]


def test_single_digits():
    assert ranked_codes([Booking("a", 3), Booking("b", 1), Booking("c", 2)]) == ["1", "2", "3"]
